use std::fmt::Write as _;
use std::fs;
use std::path::Path;

use super::model::{BuildBlocker, GalleryResult, MeshCase};

pub(crate) fn write(
    primitive_cases: &[MeshCase],
    channel_cases: &[MeshCase],
    topology_cases: &[MeshCase],
    blockers: &[BuildBlocker],
    output: &Path,
) -> GalleryResult<()> {
    let mut manifest = String::from(
        "# Figure manifest\n\nGenerated by `book_mesh_gallery`. Counts are from the actual `IndexedMesh` value; display faces may be sampled for SVG readability.\n\n| Category | Slug | Family | Parameters | Vertices | Faces | Cells | Source |\n| --- | --- | --- | --- | ---: | ---: | ---: | --- |\n",
    );
    for (category, cases) in [
        ("Primitive", primitive_cases),
        ("Channel", channel_cases),
        ("Topology", topology_cases),
    ] {
        for case in cases {
            let _ = writeln!(
                manifest,
                "| {category} | `{}` | {} | {} | {} | {} | {} | `{}` |",
                case.slug,
                case.title,
                case.parameters,
                case.mesh.vertex_count(),
                case.mesh.faces.len(),
                case.mesh.cell_count(),
                case.source
            );
        }
    }
    if !blockers.is_empty() {
        manifest.push_str(
            "\n## Blocked builder families\n\nThese public builders returned an error for the deterministic representative parameters and are not represented by fabricated geometry.\n\n| Category | Family | Error | Source |\n| --- | --- | --- | --- |\n",
        );
        for blocker in blockers {
            let _ = writeln!(
                manifest,
                "| {} | {} | `{}` | `{}` |",
                blocker.category, blocker.family, blocker.error, blocker.source
            );
        }
    }
    fs::write(output, manifest)?;
    Ok(())
}
